probe_gd:
extends SceneTree
const DB = preload("res://content/api/content_db.gd")
const Table = preload("res://combat/data/move_table.gd")
func _initialize() -> void:
	var db = DB.new()
	var table = Table.new()
	table.db = db
	var rules: Dictionary = JSON.parse_string(FileAccess.get_file_as_string("res://data/combat.json"))
	var checks := 0
	var failures := 0
	for pair in [["character/swordman/attackinfo/weaponcomboshort1.atk",100.0],["character/swordman/dsattackinfo/weaponcomboshort1.atk",100.0],["character/swordman/attackinfo/attack1.atk",85.0],["character/swordman/attackinfo/attack2.atk",100.0],["character/swordman/attackinfo/attack3.atk",120.0]]:
		var spec: Dictionary = rules["moves"]["attack1"].duplicate(true)
		spec["atk"] = pair[0]
		var stage: Dictionary = table._build_stage(spec,{})
		var actual: float = stage["hits"][0]["percent"]
		checks += 1
		if actual != pair[1]:failures += 1
		print("[ATK_BONUS_RUNTIME] ",pair[0]," percent=",actual," expected=",pair[1])
	checks += 1
	if not table.problems.is_empty():failures += 1
	print("[ATK_BONUS_RUNTIME] COMPLETE checks=",checks," failures=",failures)
	quit(0 if failures==0 else 1)
